tqua[j] = hoadonnhap[i];                     j++;                 }             }             return ketqua;         }         public static string KiemTraTinhHopLe_HDBan(HoaDonBH HD_Ban)         {             string chuoi = string.Empty;             if (HD_Ban.SL < 0 || HD_Ban.Gia < 0)             {                 chuoi = "Hoa don khong hop le";             }             return chuoi;         }         public static string KiemTraTinhHopLe_HDNhap(HoaDonNH HD_Nhap)         {             string chuoi = string.Empty;             if (HD_Nhap.SL < 0 || HD_Nhap.Gia < 0)             {                 chuoi = "Hoa don khong hop le";             }             return chuoi;         }         public static string ThemHoaDon_Ban(HoaDonBH HD_Ban)         {             string chuoi = KiemTraTinhHopLe_HDBan(HD_Ban);             bool isValid = (chuoi == string.Empty);             if (isValid)             {                 LT_HoaDon.ThemHoaDon_Ban(HD_Ban);             }             return chuoi;         }         public static string ThemHoaDon_Nhap(HoaDonNH HD_Nhap)         {             string chuoi = KiemTraTinhHopLe_HDNhap(HD_Nhap);             bool isValid = (chuoi == string.Empty);             if (isValid)             {                 LT_HoaDon.ThemHoaDon_Nhap(HD_Nhap);             }             return chuoi;         }         public static HoaDonBH DocChiTiet_HDBan(string MaHD_BH)         {             HoaDonBH? kq;             kq = LT_HoaDon.DocChiTiet_HDBan(MaHD_BH);             return kq;         }         public static HoaDonNH DocChiTiet_HDNhap(string MaHD_NH)         {             HoaDonNH? kq;             kq = LT_HoaDon.DocChiTiet_HDNhap(MaHD_NH);             return kq;         }         public static string SuaHD_Ban(HoaDonBH HD)         {             string chuoi = KiemTraTinhHopLe_HDBan(HD);             bool isValid = (chuoi == string.Empty);             if (isValid)             {                 LT_HoaDon.SuaHD_Ban(HD);             }             return chuoi;         }         public static string SuaHD_Nhap(HoaDonNH HD)         {             string chuoi = KiemTraTinhHopLe_HDNhap(HD);             bool isValid = (chuoi == string.Empty);             if (isValid)             {                 LT_HoaDon.SuaHD_Nhap(HD);             }             return chuoi;         }         public static string XoaHD_Ban(string MaHD_Ban)         {             string chuoi = string.Empty;             LT_HoaDon.XoaHD_Ban(MaHD_Ban);             return chuoi;         }         public static string XoaHD_Nhap(string MaHD_Nhap)         {             string chuoi = string.Empty;             LT_HoaDon.XoaHD_Nhap(MaHD_Nhap);             return chuoi;         }     } } 